-- ========================================================
-- 3. DATA VERIFICATION
-- ========================================================

-- Total wilayas
SELECT
    COUNT(*) AS total_wilayas
FROM wilayas;

-- Total communes
SELECT
    COUNT(*) AS total_communes
FROM communes;

-- Number of communes per wilaya
SELECT
    w.code AS wilaya_code,
    w.name AS wilaya_name,
    COUNT(c.id) AS communes_count
FROM wilayas w
LEFT JOIN communes c
    ON c.wilaya_id = w.id
GROUP BY
    w.id,
    w.code,
    w.name
ORDER BY
    CAST(w.code AS UNSIGNED);

-- Communes without a valid wilaya
SELECT
    c.id,
    c.code,
    c.name
FROM communes c
LEFT JOIN wilayas w
    ON w.id = c.wilaya_id
WHERE w.id IS NULL;



